rules=[('FRONTIER','854ba9ebd487ee034f295210ca6ddf3a','standards/EXECUTIVE_BASELINE.md §6 / The three duties, lines 627–629'),('WORK','a1b22e933a120bf64a62b705eed525c6','standards/EXECUTIVE_BASELINE.md §9, lines 1022, 1031–1032'),('ACCESS','ceb3153a383d5158244d9eb1007f200c','standards/PRODUCT_DEFINITION.md §9 / PC-04, lines 917–937; PC-05, lines 939–962'),('REUSE','177ffff4a573bab836e660497fabaed5','standards/ACTIVATION.md §7, lines 1712, 1739–1740'),('RETURN','6d77d124f18fdb7af546f68428efbb56','plugins/spec/references/COORDINATED_HANDOFF.md / Evaluate The Return, lines 169–198'),('REVIEW','1367a360c53ba1b053dedacb082887b0','standards/EXECUTIVE_BASELINE.md §10, lines 1052, 1071–1072'),('INDEPENDENCE','9c15107e315077f7ca89572a5a5ecdbf','standards/EVALUATION.md §3, lines 242–244, 259–260'),('CLOSURE','6a3093390cc241e4b4b6b99e456f294c','standards/TICKETS.md §7 / Condition-based closure and reuse, line 1241; full conjunction protocol remains external')]
