edges += [('M-frontier','D-schema','selects_bounded_unit','The granted provider candidate is dependency-ready while consumer successors are conditional.',['854ba9ebd487ee034f295210ca6ddf3a']),('M-access','D-schema','forbids_grant_union','Exports convey permitted dependency meaning, not consumer implementation access.',['ceb3153a383d5158244d9eb1007f200c']),('S2-09','I-batch-stale','changes_bound_dependency','The corrected API-1 interpretation changes the old review basis.',['S2-09','S2-11']),('S2-11','I-batch-stale','defines_prior_scope','The original receipt names schema-r11 and batch-r31.',['S2-11']),('M-reuse','I-batch-stale','invalidates_affected_reliance','Changed schema coordinate removes direct locale reliance without erasing historical observations.',['177ffff4a573bab836e660497fabaed5']),('S2-12','I-console-narrow','limits_coverage','The receipt explicitly excludes API-2.',['S2-12']),('M-reuse','I-console-narrow','preserves_exact_survivors','Retain exact API-1 evidence only where applicability still holds.',['177ffff4a573bab836e660497fabaed5']),('D-schema','D-review','supplies_exact_subject','Review awaits the returned named candidate.',['S2-19']),('M-review','D-review','conditions_assessment','Separate non-author, evidence and actual policy are required.',['1367a360c53ba1b053dedacb082887b0','9c15107e315077f7ca89572a5a5ecdbf']),('D-schema','D-successors','enables_conditionally','Identified candidate and exported contract are prerequisite to the separately authorized Batch adaptation.',['S2-07','S2-16']),('D-review','D-successors','supplies_bounded_evidence','Local review contributes evidence but creates no successor grant.',['S2-13','S2-19','6d77d124f18fdb7af546f68428efbb56']),('S2-17','D-console-block','withholds_source_effect','Pending owner message does not authorize edits.',['S2-17']),('S2-22','D-stage','reconciles_prior_effect','Current authoritative receipt establishes one commit then removal and absence at stage-19.',['S2-21','S2-22']),('S2-23','D-stage','conditions_new_effect','Distinct operator, candidate and current stage-19 are required.',['S2-23']),('M-return','D-stage','forbids_blind_retry','Timeout alone cannot license replay and prior reconciliation supplies no SC-12 network grant.',['6d77d124f18fdb7af546f68428efbb56']),('D-successors','D-m14-held','requires_remaining_results','Consumer adaptations and composition remain required beyond local candidate.',['S2-13','S2-24']),('D-console-block','D-m14-held','blocks_dependent_closure','An ungranted consumer source change cannot be assumed complete.',['S2-17']),('I-batch-stale','D-m14-held','withholds_current_assurance','Old locale assessment is not current M14 evidence.',['S2-11','S2-13']),('I-console-narrow','D-m14-held','leaves_api2_uncovered','API-1 evidence does not close API-2 agreement.',['S2-12','S2-13']),('M-closure','D-m14-held','requires_valid_conjunction','All applicable obligations/judgments must be satisfied on exact current bases.',['6a3093390cc241e4b4b6b99e456f294c'])]
